CREATE OR ALTER PROCEDURE [dbo].[MEEmrs_GetAllByTypeAndStatus] 
	@FK_MEEmrTypeID INT,
	@MEEmrStatus varchar(50)
AS
BEGIN
	SET NOCOUNT ON

	SELECT *
	FROM [dbo].[MEEmrs]
	WHERE [AAStatus] = 'Alive'
		AND [FK_MEEmrTypeID] = @FK_MEEmrTypeID
		AND [MEEmrStatus] = @MEEmrStatus
END
